import dev.hua.ptcglive.engine.*;
import dev.hua.ptcglive.engine.field.*;
import dev.hua.ptcglive.rules.*;
import java.util.*;

public final class NonPokemonBatch44Test {
    static final UUID A=GeneratedRuleBatch8Test.A,B=GeneratedRuleBatch8Test.B;
    static final List<String> IDS=List.of("xy7_en_074","sm11_en_187","xy2_en_095","xy5_en_138","xy10_en_110","bw5_en_095");
    static void check(boolean ok,String why){if(!ok)throw new AssertionError(why);}
    static TrainerProfile profile(String id){return NonPokemonBatch2Test.DATA.trainer(id).orElseThrow();}
    static CardInstance card(ServerMatch m,UUID p,String id){return DynamicPassiveModifierTest.hand(m,p,id);}
    static UUID active(ServerMatch m,UUID p){return m.activePokemonView(p).pokemonId();}
    static UUID bench(ServerMatch m,UUID p){return m.benchPokemonView(p).getFirst().pokemonId();}
    static void settle(ServerMatch m){NonPokemonBatch2Test.settle(m);}
    static ServerMatch aiGame(String id){return GeneratedRuleBatch8Test.fixture(List.of(),EnergyType.FIRE,EnergyType.GRASS,profile(id),GeneratedRuleBatch8Test.hit(100,false));}
    public static void main(String[] args){forest();blizzard();cube();earth();hooligans();System.out.println("NonPokemonBatch44Test passed: both players' first-turn and repeated Grass evolution, departing effect timing, remaining-HP attack boundary, self damage versus other attacks/counters, either basic Fire/Fighting costs and random revealed hand shuffle");}
    static void forest(){for(UUID p:List.of(A,B))for(EnergyType type:List.of(EnergyType.GRASS,EnergyType.FIRE)){
        var m=GeneratedRuleBatch8Test.fixture(List.of(),EnergyType.GRASS,type,profile("xy7_en_074"),GeneratedRuleBatch8Test.hit(100,false),1,Set.of(),true);if(p.equals(B))m.endTurn(A);m.playTrainer(p,card(m,p,"trainer").instanceId(),null);check(m.canEvolve(p,active(m,p),"evolved")== (type==EnergyType.GRASS),"Forest first turn used destination type or wrong owner");if(type==EnergyType.GRASS){m.evolve(p,active(m,p),card(m,p,"evolved").instanceId());check(m.activePokemonView(p).topCardId().equals("evolved"),"Forest did not evolve Grass into non-Grass");}m.discardStadiumByEffect(p);var fresh=card(m,p,"basic");m.playBasicPokemonToBench(p,fresh.instanceId());check(!m.canEvolve(p,m.benchPokemonView(p).getLast().pokemonId(),"evolved"),"Forest permission persisted after Stadium left");
    }var m=NonPokemonBatch39Test.game("xy7_en_074","Test",EnergyType.GRASS,Set.of(),0);m.playTrainer(A,card(m,A,"trainer").instanceId(),null);var fresh=card(m,A,"basic");m.playBasicPokemonToBench(A,fresh.instanceId());UUID host=m.benchPokemonView(A).getLast().pokemonId();m.evolve(A,host,card(m,A,"evolved").instanceId());m.evolve(A,host,card(m,A,"stage2").instanceId());check(m.benchPokemonView(A).stream().anyMatch(p->p.pokemonId().equals(host)&&p.topCardId().equals("stage2")),"Forest failed same-turn full evolution chain");}
    static void blizzard(){var m=DynamicPassiveModifierTest.fixture(DynamicPassiveModifierTest.plainTool(),profile("sm11_en_187"));m.placeDamageCountersByEffect(A,A,active(m,A),26);m.placeDamageCountersByEffect(A,B,active(m,B),25);m.playTrainer(A,card(m,A,"stadium").instanceId(),null);check(!m.mayAttack(A),"Blizzard Town allowed exactly 40 remaining HP");GeneratedRuleBatch8Test.reject(()->m.attack(A,"hit"));m.endTurn(A);check(m.mayAttack(B),"Blizzard Town blocked 50 remaining HP");m.placeDamageCountersByEffect(B,B,active(m,B),1);check(!m.mayAttack(B),"Blizzard Town ignored opponent's own HP");m.healDamageByEffect(B,B,active(m,B),10);check(m.mayAttack(B),"Blizzard attack lock cached after healing");m.discardStadiumByEffect(B);m.endTurn(B);check(m.mayAttack(A),"Blizzard lock remained after Stadium left");}
    static ServerMatch cubeGame(AttackDefinition attack){return DynamicPassiveModifierTest.fixture(profile("xy2_en_095"),DynamicPassiveModifierTest.plainStadium(),EnergyProfile.fixed(EnergyType.COLORLESS,2),attack);}
    static void cube(){for(String mode:List.of("native","self_damage","recoil"))for(boolean disabled:List.of(false,true)){
        var m=cubeGame(AttackSelfDamageCalculationTest.attack(mode,30,EnergyType.GRASS,""));m.playTrainer(A,card(m,A,"tool").instanceId(),active(m,A));if(disabled)m.disableToolEffectsByEffect(A,A,active(m,A));m.attack(A,"hit");check(m.activePokemonView(A).damage()==(disabled?60:0)&&m.activePokemonView(B).damage()==80,"Protection Cube own damage, Weakness or disabled state "+mode);m.attack(B,"hit");check(m.activePokemonView(A).damage()==(disabled?140:80),"Protection Cube stopped opponent damage");
    }var counters=cubeGame(BeforeDamageAttackTest.attack("","","{\"type\":\"damage_counter\",\"target\":\"SELF\",\"amount\":3}"));counters.playTrainer(A,card(counters,A,"tool").instanceId(),active(counters,A));counters.attack(A,"hit");check(counters.activePokemonView(A).damage()==30,"Protection Cube blocked placing counters");var bench=cubeGame(GroupBenchDamageTest.spread("OWN_BENCH",30));bench.playTrainer(A,card(bench,A,"tool").instanceId(),bench(bench,A));bench.attack(A,"hit");check(bench.benchPokemonView(A).getFirst().damage()==30,"Protection Cube blocked a different own Pokemon's attack");}
    static void earth(){for(String id:List.of("xy5_en_138","xy10_en_110"))for(EnergyType type:List.of(EnergyType.FIRE,EnergyType.FIGHTING,EnergyType.WATER)){
        var m=GeneratedRuleBatch8Test.fixture(List.of(),type,EnergyType.GRASS,profile(id),GeneratedRuleBatch8Test.hit(100,false));m.playTrainer(A,card(m,A,"trainer").instanceId(),null);for(UUID p:List.of(A,B)){if(p.equals(B))m.endTurn(A);int hand=m.privateView(p).hand().size();m.activateStadium(p,m.clientView(p).stadium().instanceId(),m.stadiumEntrySequence());var q=m.effectCardPrompt(p);check(q.candidates().stream().allMatch(c->(c.definitionId().equals("energy")&&type!=EnergyType.WATER)||(c.definitionId().equals("wrong")&&type!=EnergyType.FIRE)),"Scorched Earth accepted wrong or Special Energy");check(q.candidates().stream().anyMatch(c->c.definitionId().equals(type==EnergyType.WATER?"wrong":"energy")),"Scorched Earth missed a valid printed type");var chosen=q.candidates().getFirst();m.submitEffectCards(p,q.resolutionId(),q.step(),List.of(chosen.instanceId()));settle(m);check(m.privateView(p).hand().size()==hand+1&&m.privateView(p).discard().contains(chosen)&&!m.canActivateStadium(p),"Scorched Earth cost/draw/per-player usage");}
    }var m=aiGame("xy5_en_138");m.playTrainer(A,card(m,A,"trainer").instanceId(),null);m.discardHandCardsByEffect(A,A,m.privateView(A).hand().stream().filter(c->c.definitionId().equals("energy")).map(CardInstance::instanceId).toList());check(!m.canActivateStadium(A),"Scorched Earth accepted Special Fire or basic Water");}
    static void hooligans(){for(int count:List.of(1,2,5)){var outcomes=new HashSet<Integer>();for(int seed=0;seed<40&&outcomes.size()<2;seed++){var m=NonPokemonBatch39Test.game("bw5_en_095","Test",EnergyType.GRASS,Set.of(),seed);NonPokemonBatch2Test.trim(m,B,count,null);int deck=m.privateView(B).deck().size();var old=List.copyOf(m.privateView(B).hand());m.playTrainer(A,card(m,A,"trainer").instanceId(),null);settle(m);int removed=count-m.privateView(B).hand().size();check(removed==0||removed==Math.min(3,count),"Hooligans wrong random count");check(m.privateView(B).deck().size()==deck+removed&&old.stream().filter(c->!m.privateView(B).hand().contains(c)).allMatch(c->m.privateView(B).deck().contains(c)),"Hooligans lost random cards or moved to wrong owner's deck");outcomes.add(removed);}check(outcomes.size()==2,"Hooligans did not exercise both coin outcomes");}}
}
